  'Cbpik2GXviOwzLZI074z': ['en cada registro. Explicado para gerencia', 'menores a 2 minutos', 'cruza cada vez más', 'retroalimentar al ERP'],
  'ZV5pnMVSUeJvEJTsSiGj': ['SHA256(\\text', 'firma digital de supervisor', 'bloquea el cierre y alerta', 'protección total', 'imputando el coste del material desperdiciado'],
  'articulo-39-tacografo-registro-jornada-t': ['desde 1.001 euros', 'baremo del Ministerio'],
